use mip_codex::{adaptive_resource_repair::{self,Stats},heuristic::Repair,mps};
use std::time::{Instant,Duration};
fn main(){
 let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);let model=mps::read(&args[1]).unwrap();let point=vec![0.;model.variables.len()];assert!(Repair::new(&model).candidate_check(&point));let lower:Vec<_>=model.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=model.variables.iter().map(|v|v.upper).collect();let mut stats=Stats::default();let end=Instant::now()+Duration::from_secs(1);let x=if args[2]=="1"{adaptive_resource_repair::search_incremental_reusing(&model,&point,&lower,&upper,end,1<<20,&mut stats)}else{adaptive_resource_repair::search_incremental(&model,&point,&lower,&upper,end,1<<20,&mut stats)}.unwrap_or(point);assert!(Repair::new(&model).candidate_check(&x));let objective=model.objective(&x);let values:std::collections::BTreeMap<_,_>=model.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect();let r=serde_json::json!({"status":"primal_candidate","objective":objective,"dual_bound":null,"values":values,"adaptive_stats":stats,"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT});std::fs::write(&args[3],serde_json::to_vec_pretty(&r).unwrap()).unwrap();
}
